let audioCtx=null;
function playTone(freq=440,duration=.08,type="sine",volume=.035){try{audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==="suspended")audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(volume,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration);}catch{}}


function fmt(n){if(!Number.isFinite(n))return"∞";if(n<1000)return Math.floor(n).toLocaleString();const units=["K","M","B","T","Qa","Qi","Sx","Sp","Oc","No","Dc","Ud","Dd","Td","Qad","Qid","Sxd","Spd","Ocd","Nod"];let i=-1,v=n;while(v>=1000&&i<units.length-1){v/=1000;i++;}return(v>=100?Math.floor(v):v>=10?v.toFixed(1):v.toFixed(2))+units[i];}

