 function checkAchievements(next){const unlocked=new Set(next.achievements||[]);const totalOwned=Object.values(next.buildings||{}).reduce((a,b)=>a+b,0);for(const a of NORMAL_ACHIEVEMENTS){const [name,,type,target]=a;let ok=false;if(type==="total")ok=next.total>=target;else if(type==="asc")ok=next.cookies>=target;else if(type==="clicks")ok=next.clicks>=target;else if(type==="gold")ok=next.goldenClicks>=target;else if(type==="wrath")ok=next.wrathClicks>=target;else if(type==="wrinkler")ok=next.wrinklerPopped>=target;else if(type==="owned")ok=totalOwned>=target;else if(type==="upgrades")ok=next.purchased.length>=target;else if(type==="ascends")ok=(next.ascends||0)>=target;else if(type==="spells")ok=next.spells>=target;else if(type==="trades")ok=next.trades>=target;else if(type==="garden")ok=target===36?(next.gardenGrid||[]).filter(Boolean).length>=36:(next.gardenSeeds?.length||0)>=target||(next.plants?.length||0)>=target;else if(type==="sugar")ok=(next.sugarHarvested||0)>=target||((target===2&&next.sugarType==="bifurcated")||(target===3&&next.sugarType==="meaty")||(target===4&&next.sugarType==="caramelized")||(target===5&&next.sugarType==="golden"));else if(type==="apoc")ok=(next.elderWrath||0)>=target;else if(type==="grandcursor")ok=(next.buildings?.b2||0)+(next.buildings?.b0||0)>=target;else if(type==="building"||type==="building2"||type==="building3"||type==="building14"||type==="building17"||type==="building18"||type==="building19")ok=Object.values(next.buildings||{})[type==="building"?0:Number(type.slice(8))]>=target;else if(type==="allbuildings")ok=BUILDINGS.every(b=>(next.buildings?.[b.id]||0)>=target);else if(type==="cps")ok=(next.baseCps||0)>=target;else if(type==="news")ok=(next.newsClicks||0)>=target;else if(type==="kitten")ok=(next.purchasedKittens?.length||0)>=target;else if(type==="shadow")continue;else ok=next.total>=target;if(ok)unlocked.add("ach-"+name);}return {...next,achievements:[...unlocked]};}
